sys_script_client.script:
function onLoad() {
	// 等待页面加载完成
	setTimeout(function() {
		addSearchComponent();
	}, 1000);
}

function addSearchComponent() {
    // 检查是否已添加搜索组件
    if (g_form.getElement('customSearchContainer')) {
        return;
    }

    // 创建搜索组件
    var searchHTML = [
        '<div class="panel panel-default" id="customSearchContainer" style="margin-bottom: 15px;">',
        '    <div class="panel-heading">',
        '        <h4 class="panel-title" style="margin: 0;">🔍 快速检索</h4>',
        '    </div>',
        '    <div class="panel-body">',
        '        <div class="form-inline">',
        '            <input type="text" class="form-control" id="moduleSearchInput" ',
        '                   placeholder="输入关键词搜索..." ',
        '                   style="width: 300px; margin-right: 10px;">',
        '            <button class="btn btn-primary" onclick="performModuleSearch()">搜索</button>',
        '            <button class="btn btn-default" onclick="clearModuleSearch()" style="margin-left: 5px;">清除</button>',
        '        </div>',
        '        <div id="moduleSearchResults" style="margin-top: 10px; display: none;">',
        '            <div class="list-group" id="searchResultsList"></div>',
        '        </div>',
        '    </div>',
        '</div>'
    ].join('');

    // 插入到按钮上方
    var listHeader = g_form.getElement('x_1108048_wish_l_0_democase.ask_for');
    if (listHeader) {
        listHeader.insertAdjacentHTML('beforebegin', searchHTML);
    } else {
        // 备用插入位置
        var contentContainer = g_form.getElement('.list-content') || g_form.getElement('#content');
        if (contentContainer) {
            contentContainer.insertAdjacentHTML('afterbegin', searchHTML);
        }
    }
}

function performModuleSearch() {
    var keyword = g_form.getElement('moduleSearchInput').value;

    if (!keyword || keyword.length < 2) {
        alert('请输入至少2个字符进行搜索');
        return;
    }

    // 显示加载状态
    g_form.getElement('moduleSearchResults').style.display = 'block';
    g_form.getElement('searchResultsList').innerHTML = '<div class="list-group-item">搜索中...</div>';

    // 使用 AJAX 搜索
    var ga = new GlideAjax('CaseDemoUtils');
    ga.addParam('sysparm_name', 'searchCaseDemoRecords');
    ga.addParam('sysparm_keyword', keyword);
    ga.getXML(handleModuleSearchResponse);
}

function handleModuleSearchResponse(response) {
    var answer = response.responseXML.documentElement.getAttribute("answer");
    var results = JSON.parse(answer);
    var resultsHtml = '';

    if (results.length > 0) {
        for (var i = 0; i < results.length; i++) {
            var item = results[i];
            resultsHtml += '<a href="' + currentTableName + '.do?sys_id=' + item.sys_id + '" class="list-group-item" target="_blank">';
            resultsHtml += '<strong>' + (item.number || item.sys_id) + '</strong>: ' + (item.title || '无描述');
            resultsHtml += '</a>';
        }
    } else {
        resultsHtml = '<div class="list-group-item text-muted">未找到匹配的记录</div>';
    }

    g_form.getElement('searchResultsList').innerHTML = resultsHtml;
}

function clearModuleSearch() {
    g_form.getElement('moduleSearchInput').value = '';
    g_form.getElement('moduleSearchResults').style.display = 'none';
}

// 获取当前表名
var currentTableName = typeof g_list !== 'undefined' ? g_list.getTableName() : 'x_1108048_wish_l_0_democase';
